// The snippet ex6 asks you to predict. The gate runs it from inside a timer
// callback and compares the labels with your answer. Do not edit this file.

export function run(log: (label: string) => void): void {
  let depth = 0;

  const tick = (): void => {
    depth += 1;
    log(`tick-${depth}`);
    if (depth < 3) process.nextTick(tick);
  };

  process.nextTick(tick);
  queueMicrotask(() => log("micro"));
  setTimeout(() => log("timer"), 0);
  log("sync");
}
